// The OS bridge as the UI sees it. In the app this talks to the Rust backend
// (src-tauri); in a plain browser (npm run preview) it falls back to a mock.
// Modules never use this directly — they get ctx.system.

import { createMockBridge } from './mock-bridge.js';

async function listModules() {
  // Generated by scripts/gen-modules.js before dev/build.
  try {
    const res = await fetch('modules/index.json');
    if (res.ok) return await res.json();
  } catch {}
  return null;
}

function createTauriBridge() {
  const tauri = window.__TAURI__;
  if (!tauri?.core || !tauri?.event) return null;
  const { invoke } = tauri.core;
  const { listen } = tauri.event;

  const on = (name, fn) => {
    let unlisten = null;
    let cancelled = false;
    listen(name, (e) => fn(e.payload)).then((un) => {
      if (cancelled) un(); else unlisten = un;
    });
    return () => { cancelled = true; unlisten?.(); };
  };

  return {
    native: true,
    listModules,
    setInteractive: (interactive) => invoke('set_interactive', { interactive: !!interactive }),
    onCursor: (fn) => on('cursor', fn),
    onToggle: (fn) => on('toggle', fn),
    onAudio: (fn) => on('audio', fn),
    glass: {
      // onFrame gets an ArrayBuffer: [w u16, h u16] + BGRA pixels, whenever the screen behind changes
      start: (rect, w, h, onFrame) => {
        const frames = new tauri.core.Channel();
        frames.onmessage = onFrame;
        return invoke('glass_start', { frames, rect, outW: w, outH: h });
      },
      move: (rect, w, h) => invoke('glass_move', { rect, outW: w, outH: h }),
      stop: () => invoke('glass_stop'),
    },
    setHideFullscreen: (on) => invoke('set_hide_fullscreen', { on: !!on }),
    autostart: {
      get: () => invoke('autostart_get'),
      set: (on) => invoke('autostart_set', { on: !!on }),
    },
    version: () => tauri.app?.getVersion?.() ?? Promise.resolve(''),
    media: {
      get: () => invoke('media_get'),
      command: (cmd) => invoke('media_command', { cmd }),
      onChange: (fn) => on('media', fn),
    },
    volume: {
      get: () => invoke('volume_get'),
      set: (value) => invoke('volume_set', { value }),
    },
  };
}

export function createBridge() {
  return createTauriBridge() ?? { ...createMockBridge(), listModules: async () => (await listModules()) ?? ['media', 'timer', 'notes'] };
}
